import { Contract, Signer, BigNumber } from 'ethers';
import { TransactionRequest, TransactionResponse } from '@ethersproject/abstract-provider';
import { NumberLike, AddressLike, IActionOptions } from './types';
import { CrossChainMessenger } from '../cross-chain-messenger';
export interface IBridgeAdapter {
    messenger: CrossChainMessenger;
    l1Bridge: Contract;
    l2Bridge: Contract;
    supportsTokenPair(l1Token: AddressLike, l2Token: AddressLike): Promise<boolean>;
    approval(l1Token: AddressLike, l2Token: AddressLike, opts?: IActionOptions): Promise<BigNumber>;
    approve(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, signer: Signer, opts?: IActionOptions): Promise<TransactionResponse>;
    deposit(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, signer: Signer, opts?: IActionOptions): Promise<TransactionResponse>;
    withdraw(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, signer: Signer, opts?: IActionOptions): Promise<TransactionResponse>;
    populateTransaction: {
        approve(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<TransactionRequest>;
        deposit(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<TransactionRequest>;
        withdraw(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<TransactionRequest>;
    };
    estimateGas: {
        approve(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<BigNumber>;
        deposit(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<BigNumber>;
        withdraw(l1Token: AddressLike, l2Token: AddressLike, amount: NumberLike, opts?: IActionOptions): Promise<BigNumber>;
    };
}
